t.script:
klaviyo = function() {
    console.log("Klaviyo events are not triggered for the website administrator");
}

klaviyo.push(["track", "Viewed Product", {
    "ProductName": "",
    "ProductID": ,
    "SKU": "",
    "Price": ,
    "URL": "",
    "ImageURL": "",
}]);
klaviyo.push(["trackViewedItem", {
    "Title": "",
    "ItemId": ,
    "URL": "",
    "ImageUrl": "",
    "Metadata": {
        "Price": ,
    }
}]);

document.addEventListener('click', function(e) {
    var btn = e.target.closest('#add_to_cart, .js_check_product a.a-submit, .js_add_cart');
    if (btn) {
        var productIdInput = document.querySelector('input[name="product_id"]');
        var productId = productIdInput ? parseInt(productIdInput.value, 10) : ;
        var qtyInput = document.querySelector('input[name="add_qty"]');
        var qty = qtyInput ? parseInt(qtyInput.value, 10) : 1;
        var priceSpan = document.querySelector('.oe_price .oe_currency_value');
        var price = priceSpan ? parseFloat(priceSpan.textContent.replace(/[^0-9.]/g, '')) : ;
        var productName = document.querySelector('h1[itemprop="name"]')?.textContent.trim() || "";

        console.log("Klaviyo: Added to Cart event pushed", productName, productId, price, qty);

        klaviyo.push(["track", "Added to Cart", {
            "AddedItemProductName": productName,
            "AddedItemProductID": productId,
            "AddedItemSKU": "",
            "AddedItemPrice": price,
            "AddedItemQuantity": qty,
            "AddedItemURL": window.location.href,
            "AddedItemImageURL": "",
            "ItemNames": [productName],
            "Items": [{
                "ProductID": productId,
                "SKU": "",
                "ProductName": productName,
                "Quantity": qty,
                "ItemPrice": price,
                "RowTotal": price * qty,
                "ProductURL": window.location.href,
                "ImageURL": ""
            }]
        }]);
    }
}, true);
